{
  "name": "Smart QR Studio",
  "description": "A high-end QR code generator with real-time customization, smart title suggestions, and high-quality PNG downloads including custom labels."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface QRConfig {
  content: string;
  title: string;
  color: string;
  bgColor: string;
  size: number;
  margin: number;
}

export interface ColorOption {
  name: string;
  value: string;
}

export const PREDEFINED_COLORS: ColorOption[] = [
  { name: 'Classic Black', value: '#000000' },
  { name: 'Royal Blue', value: '#1e40af' },
  { name: 'Emerald Green', value: '#065f46' },
  { name: 'Ruby Red', value: '#991b1b' },
  { name: 'Deep Purple', value: '#5b21b6' },
  { name: 'Midnight Indigo', value: '#312e81' },
];

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { PREDEFINED_COLORS, QRConfig } from './types';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [config, setConfig] = useState<QRConfig>({
    content: 'https://google.com',
    title: 'My Website',
    color: '#000000',
    bgColor: '#ffffff',
    size: 512,
    margin: 4,
  });

  const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
  const qrRef = useRef<SVGSVGElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setConfig(prev => ({ ...prev, [name]: value }));
  };

  const suggestTitle = async () => {
    if (!config.content) return;
    setIsGeneratingTitle(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Given this content: "${config.content}", suggest a short, catchy title (max 3 words) for a QR code label. Output ONLY the title, no quotes.`,
      });
      const suggestedTitle = response.text?.trim() || 'Scanned Code';
      setConfig(prev => ({ ...prev, title: suggestedTitle }));
    } catch (error) {
      console.error('Title generation failed', error);
    } finally {
      setIsGeneratingTitle(false);
    }
  };

  const downloadQR = useCallback(() => {
    if (!qrRef.current) return;

    const svg = qrRef.current;
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    img.onload = () => {
      // Setup canvas size with padding for the title
      const padding = 60;
      const titleHeight = config.title ? 80 : 0;
      canvas.width = img.width + padding;
      canvas.height = img.height + padding + titleHeight;

      // Fill Background
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw QR Code centered
      ctx.drawImage(img, padding / 2, padding / 2);

      // Draw Title
      if (config.title) {
        ctx.fillStyle = config.color;
        ctx.font = 'bold 40px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(config.title, canvas.width / 2, img.height + padding / 2 + 10);
      }

      // Trigger Download
      const pngUrl = canvas.toDataURL('image/png');
      const downloadLink = document.createElement('a');
      downloadLink.href = pngUrl;
      downloadLink.download = `${config.title || 'qrcode'}.png`;
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
      URL.revokeObjectURL(url);
    };

    img.src = url;
  }, [config]);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 p-4 md:p-8 flex flex-col items-center">
      {/* Header */}
      <header className="w-full max-w-6xl mb-12 text-center md:text-left flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-extrabold tracking-tight text-slate-900 flex items-center justify-center md:justify-start gap-3">
            <span className="bg-indigo-600 text-white p-2 rounded-xl">
              <i className="fas fa-qrcode"></i>
            </span>
            Smart QR Studio
          </h1>
          <p className="mt-2 text-slate-500">Professional QR codes with AI-powered labeling.</p>
        </div>
        <div className="flex gap-3 justify-center">
          <button 
            onClick={downloadQR}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-full font-semibold transition-all shadow-lg hover:shadow-indigo-200 active:scale-95"
          >
            <i className="fas fa-download"></i>
            Download PNG
          </button>
        </div>
      </header>

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* Sidebar Configuration */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <i className="fas fa-cog text-slate-400"></i>
              Customization
            </h2>

            <div className="space-y-6">
              {/* Content Input */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">QR Content (URL, Text, Link)</label>
                <textarea
                  name="content"
                  value={config.content}
                  onChange={handleInputChange}
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all resize-none"
                  placeholder="https://example.com"
                />
              </div>

              {/* Title Input */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2 flex justify-between items-center">
                  Label Title (Display Only)
                  <button 
                    onClick={suggestTitle}
                    disabled={isGeneratingTitle || !config.content}
                    className="text-xs text-indigo-600 hover:text-indigo-800 font-bold uppercase tracking-wider disabled:opacity-50"
                  >
                    {isGeneratingTitle ? <i className="fas fa-spinner fa-spin mr-1"></i> : <i className="fas fa-wand-magic-sparkles mr-1"></i>}
                    AI Suggest
                  </button>
                </label>
                <input
                  type="text"
                  name="title"
                  value={config.title}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                  placeholder="Enter a title..."
                />
              </div>

              {/* Color Dropdown */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">QR Color</label>
                <div className="relative">
                  <select
                    name="color"
                    value={config.color}
                    onChange={handleInputChange}
                    className="w-full appearance-none px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all cursor-pointer"
                  >
                    {PREDEFINED_COLORS.map(color => (
                      <option key={color.value} value={color.value}>
                        {color.name}
                      </option>
                    ))}
                  </select>
                  <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                    <i className="fas fa-chevron-down text-xs"></i>
                  </div>
                </div>
              </div>

              {/* Color Palette Visualizer */}
              <div className="flex flex-wrap gap-2 pt-2">
                {PREDEFINED_COLORS.map(color => (
                  <button
                    key={color.value}
                    onClick={() => setConfig(prev => ({ ...prev, color: color.value }))}
                    className={`w-8 h-8 rounded-lg border-2 transition-all ${config.color === color.value ? 'border-slate-800 scale-110' : 'border-transparent hover:scale-105'}`}
                    style={{ backgroundColor: color.value }}
                    title={color.name}
                  />
                ))}
              </div>
            </div>
          </div>

          <div className="bg-indigo-50 rounded-2xl p-6 border border-indigo-100">
            <div className="flex gap-4">
              <div className="bg-white p-3 rounded-xl shadow-sm self-start">
                <i className="fas fa-lightbulb text-indigo-600"></i>
              </div>
              <div>
                <h3 className="font-bold text-indigo-900">Pro Tip</h3>
                <p className="text-sm text-indigo-700 mt-1">High contrast colors like Deep Indigo or Classic Black work best for reliable scanning across all mobile devices.</p>
              </div>
            </div>
          </div>
        </section>

        {/* Live Preview */}
        <section className="lg:col-span-7 flex flex-col items-center">
          <div className="w-full bg-white rounded-3xl p-12 shadow-sm border border-slate-100 flex flex-col items-center justify-center min-h-[500px] relative overflow-hidden">
            {/* Background pattern */}
            <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#4f46e5 1px, transparent 1px)', backgroundSize: '24px 24px' }}></div>

            <div className="relative z-10 flex flex-col items-center bg-white p-8 rounded-2xl shadow-xl border border-slate-50">
              <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-6 group cursor-default">
                {config.content ? (
                  <QRCodeSVG
                    ref={qrRef}
                    value={config.content}
                    size={280}
                    fgColor={config.color}
                    bgColor={config.bgColor}
                    level="H"
                    includeMargin={true}
                    className="transition-all duration-300"
                  />
                ) : (
                  <div className="w-[280px] h-[280px] flex items-center justify-center text-slate-300 italic text-sm">
                    Enter content to generate QR
                  </div>
                )}
              </div>

              {config.title && (
                <div 
                  className="text-center transition-all duration-300"
                  style={{ color: config.color }}
                >
                  <span className="text-2xl font-bold tracking-tight block px-4 py-1 rounded-lg">
                    {config.title}
                  </span>
                </div>
              )}
            </div>

            <p className="mt-12 text-slate-400 text-sm flex items-center gap-2">
              <i className="fas fa-eye"></i>
              Live Preview Updates Instantly
            </p>
          </div>

          <div className="mt-8 grid grid-cols-2 md:grid-cols-4 gap-4 w-full">
             <div className="bg-white p-4 rounded-2xl border border-slate-100 text-center">
               <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Type</span>
               <span className="font-semibold text-slate-700">SVG/PNG</span>
             </div>
             <div className="bg-white p-4 rounded-2xl border border-slate-100 text-center">
               <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Level</span>
               <span className="font-semibold text-slate-700">High (30%)</span>
             </div>
             <div className="bg-white p-4 rounded-2xl border border-slate-100 text-center">
               <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Size</span>
               <span className="font-semibold text-slate-700">512px</span>
             </div>
             <div className="bg-white p-4 rounded-2xl border border-slate-100 text-center">
               <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Color</span>
               <div className="flex items-center justify-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: config.color }}></div>
                  <span className="font-semibold text-slate-700 uppercase">{config.color}</span>
               </div>
             </div>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="mt-20 w-full max-w-6xl pt-8 border-t border-slate-200 text-center text-slate-400 text-sm pb-12">
        <p>© {new Date().getFullYear()} Smart QR Studio. All generated assets are attribution-free.</p>
      </footer>
    </div>
  );
};

export default App;

