          }

          const bx = cardX + cardPadding + (qrSize / 2) - (finalBadgeSize / 2);
          const by = cardY + cardPadding + (qrSize / 2) - (finalBadgeSize / 2);

          ctx.fillStyle = config.color;
          ctx.fillRect(bx, by, finalBadgeSize, finalBadgeSize);

